// The counter kernel: kernel contract v1, kernel numeric v1 and the bounded counter proof,
// against the reference's independently authored fixtures (tests/fixtures/, copied from
// FantasyWorldGenerator/Fixtures). The fixture expectations were written by hand or with
// openssl, not generated by either implementation.
#include "check.hpp"

#include <algorithm>
#include <cstdio>
#include <functional>
#include <string>
#include <tuple>
#include <vector>

#include "fwg/counter_kernel.hpp"
#include "fwg/sha256.hpp"
#include "product_fixtures.hpp"

using namespace fwg;
using namespace fwg::kernel;

namespace {

std::string code_of_call(const std::function<void()>& fn) {
    try {
        fn();
    } catch (const KernelError& error) {
        return error.code();
    }
    return "none";
}

JsonValue command_for(const JsonValue& state, const JsonValue::Array& events, std::int64_t target, std::int64_t budget) {
    JsonValue c = JsonValue::object();
    c.set("schema", "fantasy-world-generator.counter-command");
    c.set("schema_version", 1);
    c.set("world_id", state.at("world_id"));
    c.set("authority_epoch", state.at("authority_epoch"));
    c.set("expected_revision", state.at("revision"));
    c.set("target_time_ms", target);
    c.set("budget", budget);
    c.set("events", JsonValue(events));
    return c;
}

JsonValue with(JsonValue value, std::string_view key, JsonValue replacement) {
    value.set(key, std::move(replacement));
    return value;
}

const JsonValue& kfix() {
    static const JsonValue f = product_test::fixture("counter-kernel-v1.json");
    return f;
}

}  // namespace

TEST(kernel_numeric_fixture_canonical_bytes_and_digests) {
    const JsonValue vectors = product_test::fixture("kernel-numeric-v1.json");
    for (const JsonValue& c : vectors.at("canonical").as_array()) {
        const std::string ascii = c.at("ascii").as_string();
        check::equal(canonical_bytes(c.at("value")), ascii, "canonical bytes of " + ascii);
        check::equal(digest(c.at("value")), c.at("sha256").as_string(), "digest of " + ascii);
        check::is_true(python_equal(canonical_loads(ascii), c.at("value")), "loads round trip of " + ascii);
    }
    for (const JsonValue& s : vectors.at("streams").as_array()) {
        check::equal(random_word(s.at("seed").as_string(), s.at("stream").as_string(), s.at("index").as_int()),
                     s.at("word").as_string(), "stream word " + s.at("stream").as_string());
    }
    check::equal(unit_float("0000000000000000"), 0.0, "unit_float zero");
    check::equal(unit_float("8000000000000000"), 0.5, "unit_float half");
    check::equal(unit_float("ffffffffffffffff"), 1.0 - 1.0 / 9007199254740992.0, "unit_float max");
}

TEST(kernel_numeric_refuses_what_the_reference_refuses) {
    for (const char* text : {"1.0", "-0.0", "NaN", "Infinity", "9007199254740992", "-9007199254740992"}) {
        check::equal(code_of_call([&] { canonical_bytes(parse_json(text)); }), std::string("INVALID_INPUT"),
                     std::string("canonical_bytes refuses ") + text);
    }
    check::equal(code_of_call([&] { canonical_bytes(parse_json("\"\\ud800\"")); }), std::string("INVALID_INPUT"), "lone surrogate");
    check::equal(code_of_call([&] { canonical_bytes(JsonValue(std::string(4097, 'x'))); }), std::string("INVALID_INPUT"),
                 "string over 4096 bytes");
    check::equal(canonical_bytes(JsonValue(std::string(4096, 'x'))).size(), std::size_t{4098}, "4096 bytes accepted");
    JsonValue big = JsonValue::array();
    for (int i = 0; i < 16384; ++i) big.push_back(0);
    check::equal(code_of_call([&] { canonical_bytes(big); }), std::string("INVALID_INPUT"), "16385 nodes (the array counts)");
    big.as_array().pop_back();
    check::equal(canonical_bytes(big).size(), std::size_t{2 + 16383 * 2 - 1}, "16384 nodes accepted");
    // Depth 32 is the root plus 32 levels: 33 nested arrays put the innermost at depth 32,
    // which is allowed; 34 put it at 33. A key sits one level below its object, so an
    // object at depth 32 must be empty.
    check::equal(code_of_call([&] { canonical_bytes(parse_json(std::string(34, '[') + std::string(34, ']'))); }),
                 std::string("INVALID_INPUT"), "34 nested arrays");
    check::equal(canonical_bytes(parse_json(std::string(33, '[') + std::string(33, ']'))), std::string(33, '[') + std::string(33, ']'),
                 "33 nested arrays accepted");
    std::string nested = "{}";
    for (int i = 0; i < 32; ++i) nested = "[" + nested + "]";
    check::equal(canonical_bytes(parse_json(nested)), nested, "an empty object at depth 32 accepted");
    nested = "{\"k\":1}";
    for (int i = 0; i < 32; ++i) nested = "[" + nested + "]";
    check::equal(code_of_call([&] { canonical_bytes(parse_json(nested)); }), std::string("INVALID_INPUT"),
                 "a key at depth 33");
    // Keys count as nodes: an object of n null members is 1 + 2n nodes.
    const auto members = [](int n) {
        JsonValue object = JsonValue::object();
        for (int i = 0; i < n; ++i) object.as_object().emplace_back("k" + std::to_string(i), JsonValue());
        return object;
    };
    check::is_true(!canonical_bytes(members(8191)).empty(), "8191 members are 16383 nodes");
    check::equal(code_of_call([&] { canonical_bytes(members(8192)); }), std::string("INVALID_INPUT"),
                 "8192 members are 16385 nodes, counting the keys");
    for (const char* raw : {"{\"a\":1,\"a\":2}", "1.0", "NaN", "9007199254740992", "11111111111111111", "\"\\ud800\"",
                            "\xff", "\xef\xbb\xbf{}"}) {
        check::equal(code_of_call([&] { canonical_loads(raw); }), std::string("INVALID_INPUT"),
                     std::string("canonical_loads refuses ") + raw);
    }
    check::equal(canonical_bytes(canonical_loads("-0")), std::string("0"), "-0 decodes as zero");
    check::equal(canonical_bytes(canonical_loads("{\"b\":1, \"a\" : [ 1 ,2 ] }")), std::string("{\"a\":[1,2],\"b\":1}"),
                 "non-canonical input is normalised");
    for (const int v : {0, 2}) {
        check::equal(code_of_call([&] { canonical_bytes(JsonValue::object(), v); }), std::string("UNSUPPORTED_VERSION"),
                     "version " + std::to_string(v));
    }
    check::equal(code_of_call([&] { canonical_bytes(JsonValue::object(), -1); }), std::string("INVALID_INPUT"), "version -1");
    for (const auto& [seed, stream, index] :
         std::vector<std::tuple<const char*, const char*, std::int64_t>>{{"0", "terrain", 0},
                                                                         {"FFFFFFFFFFFFFFFF", "terrain", 0},
                                                                         {"0000000000000000", "", 0},
                                                                         {"0000000000000000", "Terrain", 0},
                                                                         {"0000000000000000", "terrain", -1},
                                                                         {"0000000000000000", "terrain", kMaxSafe + 1}}) {
        check::equal(code_of_call([&] { random_word(seed, stream, index); }), std::string("INVALID_INPUT"),
                     std::string("random_word refuses ") + seed + "/" + stream);
    }
}

TEST(kernel_contract_fixture_envelopes_and_failure_codes) {
    const JsonValue cases = product_test::fixture("kernel-contract-v1.json");
    for (const JsonValue& event : cases.at("events").as_array()) {
        check::is_true(python_equal(validate_event(event, "world:demo"), event), "valid event");
    }
    for (const JsonValue& command : cases.at("commands").as_array()) {
        check::is_true(python_equal(validate_command(command), command), "valid command");
    }
    for (const JsonValue& c : cases.at("invalid").as_array()) {
        const bool is_command = c.at("kind").as_string() == "command";
        std::string code;
        try {
            if (is_command) {
                validate_command(c.at("value"));
            } else {
                validate_event(c.at("value"), "world:demo");
            }
            code = "none";
        } catch (const KernelError& error) {
            code = error.code();
            const JsonValue doc = error.document();
            check::equal(doc.at("schema").as_string(), std::string("fantasy-world-generator.failure"), "failure schema");
            check::equal(doc.at("schema_version").as_int(), std::int64_t{1}, "failure v1");
            check::equal(doc.size(), std::size_t{4}, "exactly schema, schema_version, code, message");
        }
        check::equal(code, c.at("code").as_string(), "code for " + dump_json(c.at("value")).substr(0, 120));
    }
}

TEST(kernel_contract_types_ids_and_budget_fail_explicitly) {
    const JsonValue cases = product_test::fixture("kernel-contract-v1.json");
    const JsonValue& event = cases.at("events").at(0);
    for (const char* field : {"time_ms", "delta", "schema_version"}) {
        for (const char* bad : {"true", "1.0", "\"1\"", "null"}) {
            check::is_true(code_of_call([&] { validate_event(with(event, field, parse_json(bad)), "world:demo"); }) != "none",
                           std::string(field) + " refuses " + bad);
        }
    }
    for (const char* key : {"event_id", "actor_id"}) {
        for (const std::string bad : {std::string(""), std::string("DISPLAY NAME"), std::string("../escape"),
                                      std::string("event:UPPER"), "event:" + std::string(65, 'a')}) {
            check::equal(code_of_call([&] { validate_event(with(event, key, JsonValue(bad)), "world:demo"); }),
                         std::string("INVALID_INPUT"), std::string(key) + " refuses " + bad);
        }
    }
    const JsonValue& command = cases.at("commands").at(0);
    for (const char* bad : {"0", "65", "true", "1.0", "\"1\""}) {
        check::equal(code_of_call([&] { validate_command(with(command, "budget", parse_json(bad))); }),
                     std::string("WORK_BUDGET"), std::string("budget ") + bad);
    }
    check::equal(code_of_call([&] { validate_command(with(command, "events", JsonValue())); }), std::string("INVALID_INPUT"),
                 "events null");
    JsonValue::Array many(65, event);
    check::equal(code_of_call([&] { validate_command(with(command, "events", JsonValue(many))); }),
                 std::string("STATE_CAPACITY"), "65 events");
}

TEST(kernel_counter_fixture_checkpoint_and_completion) {
    const JsonValue& f = kfix();
    check::is_true(initialize("world:demo") == f.at("initial"), "initialize is the fixture's initial state");
    const Candidate first = evaluate(f.at("initial"), f.at("first_command"));
    check::equal(first.work_used, std::int64_t{1}, "one budget unit spent");
    check::equal(first.next_state, canonical_bytes(f.at("checkpoint")), "checkpoint bytes");
    check::equal(first.effects, canonical_bytes(f.at("checkpoint").at("receipts")), "effects are the new receipts");
    const JsonValue checkpoint = commit(f.at("initial"), first);
    const JsonValue done = commit(checkpoint, evaluate(checkpoint, f.at("resume_command")));
    check::equal(dump_snapshot(done), canonical_bytes(f.at("complete")), "completion bytes");
    check::equal(load_candidate(dump_candidate(first)) == first, true, "candidate transport round trip");
}

TEST(kernel_counter_retries_duplicates_and_tampering) {
    const JsonValue& f = kfix();
    const Candidate first = evaluate(f.at("initial"), f.at("first_command"));
    check::is_true(first == evaluate(f.at("initial"), f.at("first_command")), "evaluation is a pure function");
    const JsonValue next = commit(f.at("initial"), first);
    check::equal(dump_snapshot(commit(next, first)), dump_snapshot(next), "a duplicate commit is a no-op");
    Candidate tampered = first;
    tampered.next_state = canonical_bytes(with(f.at("checkpoint"), "counter", JsonValue(999)));
    check::equal(code_of_call([&] { commit(f.at("initial"), tampered); }), std::string("INVALID_CANDIDATE"), "tampered");
    tampered = first;
    tampered.work_used = 65;
    check::equal(code_of_call([&] { commit(f.at("initial"), tampered); }), std::string("INVALID_CANDIDATE"), "work over 64");

    // Reordered and repeated inputs produce the same candidate.
    const JsonValue::Array& events = f.at("events").as_array();
    const JsonValue state = f.at("initial");
    JsonValue::Array reversed(events.rbegin(), events.rend());
    JsonValue::Array repeated = events;
    repeated.push_back(events.front());
    const Candidate a = evaluate(state, command_for(state, events, 10, 64));
    check::is_true(a == evaluate(state, command_for(state, reversed, 10, 64)), "order-free");
    check::is_true(a == evaluate(state, command_for(state, repeated, 10, 64)), "identical repeats collapse");

    // Effects are applied in (time_ms, event_id) order: an early event with a late id first.
    const JsonValue late_id = with(with(events.at(0), "event_id", JsonValue("event:z")), "time_ms", JsonValue(1));
    const JsonValue early_id = with(with(events.at(0), "event_id", JsonValue("event:a")), "time_ms", JsonValue(5));
    const Candidate ordered = evaluate(state, command_for(state, {early_id, late_id}, 10, 1));
    check::is_true(canonical_loads(ordered.effects).at(0).at("event").at("event_id") == JsonValue("event:z"),
                   "time orders before id");

    // A completed delivery retry is a no-op even with an old revision; a future one is stale.
    const JsonValue done = commit(state, a);
    const JsonValue request = command_for(state, events, 10, 64);
    const Candidate retry = evaluate(done, request);
    check::equal(retry.work_used, std::int64_t{0}, "retry does no work");
    check::equal(retry.effects, std::string("[]"), "retry has no effects");
    JsonValue future = request;
    future.set("expected_revision", done.at("revision").as_int() + 1);
    check::equal(code_of_call([&] { evaluate(done, future); }), std::string("STALE_REVISION"), "future revision");
}

TEST(kernel_counter_conflicts_fences_and_intervals) {
    const JsonValue& f = kfix();
    const JsonValue state = f.at("initial");
    const JsonValue& event = f.at("events").at(0);
    const JsonValue changed = with(event, "delta", JsonValue(99));
    check::equal(code_of_call([&] { evaluate(state, command_for(state, {event, changed}, 10, 64)); }),
                 std::string("CONFLICTING_EVENT"), "conflict within a batch");
    const JsonValue& checkpoint = f.at("checkpoint");
    check::equal(code_of_call([&] { evaluate(checkpoint, command_for(checkpoint, {changed}, 10, 64)); }),
                 std::string("CONFLICTING_EVENT"), "conflict with a receipt");
    const JsonValue request = command_for(state, f.at("events").as_array(), 10, 64);
    check::equal(code_of_call([&] { evaluate(state, with(request, "expected_revision", JsonValue(1))); }),
                 std::string("STALE_REVISION"), "stale revision");
    check::equal(code_of_call([&] { evaluate(state, with(request, "authority_epoch", JsonValue(1))); }),
                 std::string("AUTHORITY_MISMATCH"), "epoch");
    check::equal(code_of_call([&] {
                     evaluate(state, with(with(request, "world_id", JsonValue("world:other")), "events", JsonValue::array()));
                 }),
                 std::string("UNKNOWN_ID"), "another world");
    check::equal(code_of_call([&] { evaluate(checkpoint, command_for(checkpoint, {}, 20, 64)); }),
                 std::string("INTERVAL_CONFLICT"), "a pending target cannot move");
    const JsonValue late = with(with(event, "event_id", JsonValue("event:new")), "time_ms", JsonValue(1));
    check::equal(code_of_call([&] { evaluate(checkpoint, command_for(checkpoint, {late}, 10, 64)); }),
                 std::string("INTERVAL_CONFLICT"), "no insertion into a pending interval");
    // The whole interval is validated before any partial work.
    const JsonValue huge = with(event, "delta", JsonValue(kMaxSafe));
    const JsonValue one = with(f.at("events").at(1), "delta", JsonValue(1));
    check::equal(code_of_call([&] { evaluate(state, command_for(state, {huge, one}, 10, 1)); }),
                 std::string("NUMERIC_OVERFLOW"), "overflow across the interval");
    for (const int t : {0, 11}) {
        check::equal(code_of_call([&] { evaluate(state, command_for(state, {huge, with(one, "time_ms", JsonValue(t))}, 10, 1)); }),
                     std::string("INTERVAL_CONFLICT"), "event outside (0, 10] at " + std::to_string(t));
    }
}

TEST(kernel_counter_budget_partitions_and_capacity) {
    const JsonValue& f = kfix();
    const JsonValue initial = f.at("initial");
    std::vector<std::int64_t> revisions;
    for (const std::int64_t budget : {1, 2, 3}) {
        JsonValue state = commit(initial, evaluate(initial, command_for(initial, f.at("events").as_array(), 10, budget)));
        while (!state.at("pending").is_null()) state = commit(state, evaluate(state, command_for(state, {}, 10, budget)));
        revisions.push_back(state.at("revision").as_int());
        check::equal(canonical_bytes(state.at("receipts")), canonical_bytes(f.at("complete").at("receipts")),
                     "same receipts at budget " + std::to_string(budget));
    }
    check::is_true(revisions == std::vector<std::int64_t>{3, 2, 1}, "commit counts differ, effects do not");

    // 256 receipts retained and never evicted.
    JsonValue state = initial;
    for (int batch = 0; batch < 4; ++batch) {
        JsonValue::Array events;
        for (int i = 0; i < 64; ++i) {
            char id[32];
            std::snprintf(id, sizeof id, "event:e%03d", batch * 64 + i);
            events.push_back(with(with(with(f.at("events").at(0), "event_id", JsonValue(id)), "time_ms", JsonValue(batch + 1)),
                                  "delta", JsonValue(1)));
        }
        state = commit(state, evaluate(state, command_for(state, events, batch + 1, 64)));
    }
    check::equal(state.at("receipts").size(), std::size_t{256}, "256 retained");
    const JsonValue overflow = with(with(f.at("events").at(0), "event_id", JsonValue("event:overflow")), "time_ms", JsonValue(5));
    check::equal(code_of_call([&] { evaluate(state, command_for(state, {overflow}, 5, 64)); }), std::string("STATE_CAPACITY"),
                 "no eviction");
    const JsonValue duplicate = state.at("receipts").at(0).at("event");
    check::equal(dump_snapshot(commit(state, evaluate(state, command_for(state, {duplicate}, 4, 64)))), dump_snapshot(state),
                 "an old delivery is still acknowledged");
}

TEST(kernel_counter_corrupt_snapshots_are_refused) {
    const JsonValue& checkpoint = kfix().at("checkpoint");
    for (const auto& [field, value] : std::vector<std::pair<const char*, const char*>>{
             {"counter", "99"}, {"time_ms", "20"}, {"schema_version", "2"}, {"revision", "true"}}) {
        check::is_true(code_of_call([&] { load_snapshot(canonical_bytes(with(checkpoint, field, parse_json(value)))); }) != "none",
                       std::string("corrupt ") + field);
    }
    for (const char* field : {"schema_version", "rules_version", "numeric_version"}) {
        check::equal(code_of_call([&] { load_snapshot(canonical_bytes(with(checkpoint, field, JsonValue(2)))); }),
                     std::string("UNSUPPORTED_VERSION"), std::string("an unknown ") + field);
    }
    JsonValue reversed = checkpoint;
    JsonValue::Array& pending = reversed.at("pending").at("events").as_array();
    std::reverse(pending.begin(), pending.end());
    check::equal(code_of_call([&] { load_snapshot(canonical_bytes(reversed)); }), std::string("INVALID_INPUT"), "order");
    JsonValue doubled = kfix().at("complete");
    doubled.at("receipts").push_back(doubled.at("receipts").at(0));
    check::equal(code_of_call([&] { dump_snapshot(doubled); }), std::string("INVALID_INPUT"), "a repeated receipt");
}
